(5635886, 816597, 99263, '<td valign="top">Lovely high key portrait. Beautiful little girl with stunning innocent eyes and a lovely angelic face.</td>', 'Lovely high key portrait. Beautiful little girl with stunning innocent eyes and a lovely angelic face.', '2009-09-04 13:31:40.000000', NULL, 1),
(5635888, 817055, 99263, '<td valign="top">Very nicely executed "swoosh" shot. Great timing.</td>', 'Very nicely executed "swoosh" shot. Great timing.', '2009-09-04 13:32:25.000000', NULL, 1),
(5635889, 818506, 99263, '<td valign="top">Very sultry and sexy lady. Nice execution, composition and lighting.</td>', 'Very sultry and sexy lady. Nice execution, composition and lighting.', '2009-09-04 13:33:25.000000', NULL, 1),
(5635890, 817506, 99263, '<td valign="top">Powerful image with striking clouds.</td>', 'Powerful image with striking clouds.', '2009-09-04 13:33:52.000000', NULL, 1),
(5635891, 817264, 99263, '<td valign="top">Explosive and well executed fireworks image.</td>', 'Explosive and well executed fireworks image.', '2009-09-04 13:34:31.000000', NULL, 1),
(5635893, 817623, 99263, '<td valign="top">Beautiful and strikingly tranquil nature scene. I like how the solitary surfer is dwarfed by the beauty of his surroundings.</td>', 'Beautiful and strikingly tranquil nature scene. I like how the solitary surfer is dwarfed by the beauty of his surroundings.', '2009-09-04 13:36:49.000000', NULL, 1),
(5635895, 818231, 99263, '<td valign="top">Lovely character study with lots of expression and feeling. Her eyes and face show that her life has not always been a bed of roses. Excellent lighting.</td>', 'Lovely character study with lots of expression and feeling. Her eyes and face show that her life has not always been a bed of roses. Excellent lighting.', '2009-09-04 13:37:26.000000', NULL, 1),
(5635907, 817460, 99263, '<td valign="top">Interesting technique employed here. Looks like a charcoal drawing. Nicely composed and interesting set up.</td>', 'Interesting technique employed here. Looks like a charcoal drawing. Nicely composed and interesting set up.', '2009-09-04 13:47:14.000000', NULL, 1),
(5635933, 817236, 7743, '<td valign="top">I like the silhouette however feel there is too much water in the foreground.  Cropping so just a sliver of water is showing at the bottom of the image I think would make it much more appealing.</td>', 'I like the silhouette however feel there is too much water in the foreground.  Cropping so just a sliver of water is showing at the bottom of the image I think would make it much more appealing.', '2009-09-04 14:19:49.000000', NULL, 1),
(5635936, 818001, 7743, '<td valign="top">Love the symmetry however the bright bits at the right and left edges are a bit distracting.  Cropping to eliminate those I think would help.</td>', 'Love the symmetry however the bright bits at the right and left edges are a bit distracting.  Cropping to eliminate those I think would help.', '2009-09-04 14:21:17.000000', NULL, 1),
(5635939, 817361, 7743, '<td valign="top">I like the pastel colors.  Cropping the empty space from the left I think would make the image feel less static.</td>', 'I like the pastel colors.  Cropping the empty space from the left I think would make the image feel less static.', '2009-09-04 14:24:20.000000', NULL, 1),
(5635954, 814810, 99263, '<td valign="top">A little bit too high key for me.</td>', 'A little bit too high key for me.', '2009-09-04 14:41:13.000000', NULL, 1),
(5635962, 818249, 107625, '<td valign="top">Would have been a great one for the "lines" catagory!</td>', 'Would have been a great one for the "lines" catagory!', '2009-09-04 14:50:38.000000', NULL, 1),
(5636040, 817152, 102278, '<td valign="top">Nice candid shot.</td>', 'Nice candid shot.', '2009-09-04 16:51:10.000000', NULL, 1),
(5636043, 818298, 102278, '<td valign="top">I do like a lot of abstract macro stuff but this isn''t really doing it for me really. I think perhaps my problem is maybe that it is not abstract or macro enough. If it was a lot closer, and perhaps with more contrast to bring the texture of the wood out.</td>', 'I do like a lot of abstract macro stuff but this isn''t really doing it for me really. I think perhaps my problem is maybe that it is not abstract or macro enough. If it was a lot closer, and perhaps with more contrast to bring the texture of the wood out.', '2009-09-04 16:54:01.000000', NULL, 1),
(5636044, 814602, 102278, '<td valign="top">Good sunset. I like how the seaweed (?) leads the eye around.</td>', 'Good sunset. I like how the seaweed (?) leads the eye around.', '2009-09-04 16:54:51.000000', NULL, 1),
(5636045, 814810, 102278, '<td valign="top">I like the idea and the negative space to the left of the shot.</td>', 'I like the idea and the negative space to the left of the shot.', '2009-09-04 16:55:29.000000', NULL, 1),
(5636046, 814496, 102278, '<td valign="top">I like the splash in front of the duck. This adds some energy and movement to the shot.</td>', 'I like the splash in front of the duck. This adds some energy and movement to the shot.', '2009-09-04 16:56:42.000000', NULL, 1),
(5636047, 816381, 102278, '<td valign="top">Nice composition. The trees frame the shot well.</td>', 'Nice composition. The trees frame the shot well.', '2009-09-04 16:57:08.000000', NULL, 1),
(5636048, 815005, 102278, '<td valign="top">Nice sense of scale in this.</td>', 'Nice sense of scale in this.', '2009-09-04 16:57:25.000000', NULL, 1),
(5636049, 818368, 102278, '<td valign="top">I like the simplicity of this shot. If anything i would have liked more cropped off the top to leave the horizon in the middle. Good to break a few rules occasionally.</td>', 'I like the simplicity of this shot. If anything i would have liked more cropped off the top to leave the horizon in the middle. Good to break a few rules occasionally.', '2009-09-04 16:59:20.000000', NULL, 1),
(5636050, 814308, 102278, '<td valign="top">Nice portrait.</td>', 'Nice portrait.', '2009-09-04 16:59:53.000000', NULL, 1),
(5636051, 817529, 102278, '<td valign="top">Interesting composition. I like it.</td>', 'Interesting composition. I like it.', '2009-09-04 17:00:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5636052, 815400, 102278, '<td valign="top">Nicely shot to get the reflection of the light in position.</td>', 'Nicely shot to get the reflection of the light in position.', '2009-09-04 17:01:36.000000', NULL, 1),
(5636054, 811901, 102278, '<td valign="top">Nice sunset. The composition works well.</td>', 'Nice sunset. The composition works well.', '2009-09-04 17:04:41.000000', NULL, 1),
