(5636212, 815223, 100831, '<td valign="top">can''t vote</td>', 'can''t vote', '2009-09-04 20:15:58.000000', NULL, 1),
(5636214, 814810, 100831, '<td valign="top">I have now tried this on three monitors and I have to say that I still can barely make out the bear. Nice idea though. I think I''ll absent myself from voting.</td>', 'I have now tried this on three monitors and I have to say that I still can barely make out the bear. Nice idea though. I think I''ll absent myself from voting.', '2009-09-04 20:17:48.000000', NULL, 1),
