(5636221, 818269, 100831, '<td valign="top">Excellent abstract - wonderful color</td>', 'Excellent abstract - wonderful color', '2009-09-04 20:19:47.000000', NULL, 1),
(5636228, 812366, 100831, '<td valign="top">he he he. this is terrific - excellent details and colors and a very nice composition!</td>', 'he he he. this is terrific - excellent details and colors and a very nice composition!', '2009-09-04 20:29:06.000000', NULL, 1),
(5636272, 817546, 24486, '<td valign="top">Brilliant timing.</td>', 'Brilliant timing.', '2009-09-04 22:13:07.000000', NULL, 1),
