(5636438, 812823, 62895, '<td valign="top">great architecture, the processing is pushing the limits for me, but it''s not overdone. I like it, nice work!</td>', 'great architecture, the processing is pushing the limits for me, but it''s not overdone. I like it, nice work!', '2009-09-05 00:46:10.000000', NULL, 1),
(5636440, 812583, 62895, '<td valign="top">Beautiful mist, I love the glowing eeriness of this photo. 8</td>', 'Beautiful mist, I love the glowing eeriness of this photo. 8', '2009-09-05 00:46:29.000000', NULL, 1),
(5636495, 817118, 95101, '<td valign="top">Very cool building, so much color in it.</td>', 'Very cool building, so much color in it.', '2009-09-05 01:52:09.000000', NULL, 1),
(5636505, 816738, 95101, '<td valign="top">Don''t know where this is , but your photo makes me want to go there:)</td>', 'Don''t know where this is , but your photo makes me want to go there:)', '2009-09-05 01:57:10.000000', NULL, 1),
(5636507, 818340, 95101, '<td valign="top">What an adorable model you have!</td>', 'What an adorable model you have!', '2009-09-05 01:59:39.000000', NULL, 1),
