(5636558, 817864, 63812, '<td valign="top">excellent!</td>', 'excellent!', '2009-09-05 03:26:29.000000', NULL, 1),
(5636577, 817870, 99263, '<td valign="top">Absolutely amazing and dramatic sky. Never seen a sky like this before. It has the texture and look of a blazing, billowing ball of fire except it''s not red and yellow but shades of gray. The almost post apocalyptic silhouetted skyline looks dwarfed and overwhelmed by the explosion of furious sky. Really an impressive and very unusual image.</td>', 'Absolutely amazing and dramatic sky. Never seen a sky like this before. It has the texture and look of a blazing, billowing ball of fire except it''s not red and yellow but shades of gray. The almost post apocalyptic silhouetted skyline looks dwarfed and overwhelmed by the explosion of furious sky. Really an impressive and very unusual image.', '2009-09-05 05:14:51.000000', NULL, 1),
(5636579, 818039, 99263, '<td valign="top">Lovely colorful panned action shot.</td>', 'Lovely colorful panned action shot.', '2009-09-05 05:19:44.000000', NULL, 1),
(5636580, 818215, 99263, '<td valign="top">Very cool and unusual shot. Just a little dark perhaps.</td>', 'Very cool and unusual shot. Just a little dark perhaps.', '2009-09-05 05:23:53.000000', NULL, 1),
(5636581, 812731, 99263, '<td valign="top">Wonderful sunrise capture. I know Umhlanga Rocks very well. I often spent a night at the Oyster Box Hotel there. I remember that Umhlanga had a very striking lighthouse on the beach too. Durb''s was always very cool :)</td>', 'Wonderful sunrise capture. I know Umhlanga Rocks very well. I often spent a night at the Oyster Box Hotel there. I remember that Umhlanga had a very striking lighthouse on the beach too. Durb''s was always very cool :)', '2009-09-05 05:29:15.000000', NULL, 1),
(5636583, 817604, 99263, '<td valign="top">Very nicely done still life with excellent lighting.</td>', 'Very nicely done still life with excellent lighting.', '2009-09-05 05:30:42.000000', NULL, 1),
