(5637316, 816763, 102278, '<td valign="top">Great colours. Could do with some foreground in the shot maybe. Get down there and get your feet wet! :)</td>', 'Great colours. Could do with some foreground in the shot maybe. Get down there and get your feet wet! :)', '2009-09-05 19:34:07.000000', NULL, 1),
(5637319, 818336, 102278, '<td valign="top">The obvious fault here is the white flower in the way. Doesn''t make for a great shot. But the bird is looking good. Very hard to get this type of shot i''m sure.</td>', 'The obvious fault here is the white flower in the way. Doesn''t make for a great shot. But the bird is looking good. Very hard to get this type of shot i''m sure.', '2009-09-05 19:36:51.000000', NULL, 1),
(5637321, 816015, 102278, '<td valign="top">I think a wider crop would help this. Chop out most of that sky.</td>', 'I think a wider crop would help this. Chop out most of that sky.', '2009-09-05 19:38:28.000000', NULL, 1),
(5637346, 817472, 75192, '<td valign="top">This looks like a picture of a drawing... is it?</td>', 'This looks like a picture of a drawing... is it?', '2009-09-05 20:08:05.000000', NULL, 1),
(5637349, 816045, 75192, '<td valign="top">This is very beautiful. 10 from me.</td>', 'This is very beautiful. 10 from me.', '2009-09-05 20:15:44.000000', NULL, 1),
(5637353, 816294, 86799, '<td valign="top">Wonderful.  One of my favorites of the FS.  ETA - I would like to see this big, in full deatil.  Great contrast, but with subtle shading and smooth lines and textures.  Sweet, indeed.  Bumped to the top.</td>', 'Wonderful.  One of my favorites of the FS.  ETA - I would like to see this big, in full deatil.  Great contrast, but with subtle shading and smooth lines and textures.  Sweet, indeed.  Bumped to the top.', '2009-09-05 20:20:28.000000', NULL, 1),
(5637356, 816784, 86799, '<td valign="top">The comp and lighting and detail on this is outstanding.  The depth is helped a lot by your choice of vantage point.  Very well done.</td>', 'The comp and lighting and detail on this is outstanding.  The depth is helped a lot by your choice of vantage point.  Very well done.', '2009-09-05 20:21:07.000000', NULL, 1),
(5637357, 815623, 86799, '<td valign="top">Not sure this will appeal to everyone, but I love it.  I have a couple similar, but with not as much drama as this.  Very nice.</td>', 'Not sure this will appeal to everyone, but I love it.  I have a couple similar, but with not as much drama as this.  Very nice.', '2009-09-05 20:21:10.000000', NULL, 1),
(5637361, 815223, 102278, '<td valign="top">Technically very good. I find the concept a bit clunky and heavy handed though. That is often the nature of anti-drug and drink campaigns though i suppose.</td>', 'Technically very good. I find the concept a bit clunky and heavy handed though. That is often the nature of anti-drug and drink campaigns though i suppose.', '2009-09-05 20:37:52.000000', NULL, 1),
(5637362, 817879, 102278, '<td valign="top">It''s losing a bit more foreground interest i think. There is a dead patch to the bottom. Maybe something that leads the eye up to the fantastic castle.</td>', 'It''s losing a bit more foreground interest i think. There is a dead patch to the bottom. Maybe something that leads the eye up to the fantastic castle.', '2009-09-05 20:39:34.000000', NULL, 1),
(5637363, 818205, 102278, '<td valign="top">I really like the cave as framing on this shot. Good stuff</td>', 'I really like the cave as framing on this shot. Good stuff', '2009-09-05 20:39:43.000000', NULL, 1),
(5637364, 815282, 102278, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2009-09-05 20:39:47.000000', NULL, 1),
(5637365, 815373, 102278, '<td valign="top">I like the composition here.</td>', 'I like the composition here.', '2009-09-05 20:39:55.000000', NULL, 1),
(5637366, 818362, 102278, '<td valign="top">Great composition.</td>', 'Great composition.', '2009-09-05 20:39:59.000000', NULL, 1),
(5637367, 817556, 102278, '<td valign="top">Good composition.</td>', 'Good composition.', '2009-09-05 20:40:10.000000', NULL, 1),
(5637368, 816808, 102278, '<td valign="top">Great composition here. Lots of movement using the space on the left. Good shot</td>', 'Great composition here. Lots of movement using the space on the left. Good shot', '2009-09-05 20:40:19.000000', NULL, 1),
(5637369, 814204, 102278, '<td valign="top">Nice silhouette. Not so sure about the composition though. Maybe a closer crop?</td>', 'Nice silhouette. Not so sure about the composition though. Maybe a closer crop?', '2009-09-05 20:40:32.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5637370, 818313, 102278, '<td valign="top">I''d like this if you got in a bit nearer. The green on other side doesn''t add much and distracts a bit. It''s not needed i feel.</td>', 'I''d like this if you got in a bit nearer. The green on other side doesn''t add much and distracts a bit. It''s not needed i feel.', '2009-09-05 20:40:35.000000', NULL, 1),
(5637383, 816294, 7743, '<td valign="top">Lovely.  Looks like a Ted Harrison painting.</td>', 'Lovely.  Looks like a Ted Harrison painting.', '2009-09-05 20:51:33.000000', NULL, 1),
(5637399, 814986, 102278, '<td valign="top">Good wildlife shot but it really need a better position i feel. As a viewer all we get is the twigs of wood really. A closer  shot on the birds from a more interesting angle would help.</td>', 'Good wildlife shot but it really need a better position i feel. As a viewer all we get is the twigs of wood really. A closer  shot on the birds from a more interesting angle would help.', '2009-09-05 21:07:26.000000', NULL, 1),
(5637402, 817295, 102278, '<td valign="top">I do like the scale and texture on this shot.</td>', 'I do like the scale and texture on this shot.', '2009-09-05 21:09:23.000000', NULL, 1),
(5637405, 815023, 102278, '<td valign="top">Would be better for me if the head was the focus of the shot. It''s an odd composition as it is i feel. - (later) Actually, i''ve come back to this photograph and spent more time looking at it, and my initial thoughts have changed.  I really do like it a lot more now. The unusual focus really makes the shot, give it a kind of mysterious air which can be lacking in a lot of the usual insect macro shots. It''s great. Bumping my voting score from a 5 to an 8. I really like this!</td>', 'Would be better for me if the head was the focus of the shot. It''s an odd composition as it is i feel. - (later) Actually, i''ve come back to this photograph and spent more time looking at it, and my initial thoughts have changed.  I really do like it a lot more now. The unusual focus really makes the shot, give it a kind of mysterious air which can be lacking in a lot of the usual insect macro shots. It''s great. Bumping my voting score from a 5 to an 8. I really like this!', '2009-09-05 21:16:46.000000', NULL, 1),
(5637411, 817243, 57447, '<td valign="top">I like these funny looking animals.</td>', 'I like these funny looking animals.', '2009-09-05 21:40:00.000000', NULL, 1),
(5637419, 817974, 57447, '<td valign="top">Sensational lighting and focus.</td>', 'Sensational lighting and focus.', '2009-09-05 21:46:14.000000', NULL, 1),
(5637420, 817257, 57447, '<td valign="top">Needs some tone and saturation adjustments but I like that wall.</td>', 'Needs some tone and saturation adjustments but I like that wall.', '2009-09-05 21:47:25.000000', NULL, 1),
(5637421, 817883, 57447, '<td valign="top">Good focus on the frog.</td>', 'Good focus on the frog.', '2009-09-05 21:48:18.000000', NULL, 1),
(5637423, 817275, 57447, '<td valign="top">I like the view this lens provides, also great processing.</td>', 'I like the view this lens provides, also great processing.', '2009-09-05 21:50:33.000000', NULL, 1),
(5637424, 812846, 57447, '<td valign="top">Nice pastel tone.</td>', 'Nice pastel tone.', '2009-09-05 21:50:57.000000', NULL, 1),
(5637425, 817501, 57447, '<td valign="top">I like the angle used.</td>', 'I like the angle used.', '2009-09-05 21:51:21.000000', NULL, 1),
(5637427, 816339, 57447, '<td valign="top">Nice processing, really spices up an area that I would think is very beautiful.</td>', 'Nice processing, really spices up an area that I would think is very beautiful.', '2009-09-05 21:54:01.000000', NULL, 1),
(5637429, 817488, 57447, '<td valign="top">I''ve been trying to get a shot of one of these, good job.</td>', 'I''ve been trying to get a shot of one of these, good job.', '2009-09-05 21:55:15.000000', NULL, 1),
(5637433, 815638, 98339, '<td valign="top">ahhh...was it injured?</td>', 'ahhh...was it injured?', '2009-09-05 21:58:24.000000', NULL, 1),
(5637435, 816738, 98339, '<td valign="top">love the leading lines in this...excellent shot</td>', 'love the leading lines in this...excellent shot', '2009-09-05 21:58:49.000000', NULL, 1),
(5637436, 817235, 57447, '<td valign="top">It''s hard for me to put all the elements of this together but I like it.</td>', 'It''s hard for me to put all the elements of this together but I like it.', '2009-09-05 21:58:55.000000', NULL, 1),
(5637437, 817698, 57447, '<td valign="top">I like this.</td>', 'I like this.', '2009-09-05 21:59:42.000000', NULL, 1),
(5637438, 818196, 98339, '<td valign="top">wow...this is absolutely beautiful...breath taking...</td>', 'wow...this is absolutely beautiful...breath taking...', '2009-09-05 22:00:55.000000', NULL, 1),
(5637439, 817604, 57447, '<td valign="top">Very well done.  I hope it ends up in the top ten.</td>', 'Very well done.  I hope it ends up in the top ten.', '2009-09-05 22:01:59.000000', NULL, 1),
(5637444, 817604, 98339, '<td valign="top">this is stunning...I love it...</td>', 'this is stunning...I love it...', '2009-09-05 22:09:20.000000', NULL, 1),
(5637450, 818510, 76335, '<td valign="top">Good clean fun! Good job freezing the action.</td>', 'Good clean fun! Good job freezing the action.', '2009-09-05 22:17:03.000000', NULL, 1),
(5637451, 818005, 76335, '<td valign="top">Would like to have seen more shadow detail. Still very nice.</td>', 'Would like to have seen more shadow detail. Still very nice.', '2009-09-05 22:17:22.000000', NULL, 1),
(5637452, 813660, 76335, '<td valign="top">Excellent! Very well composed. The colors, textures and arrangement of shapes are terrific.</td>', 'Excellent! Very well composed. The colors, textures and arrangement of shapes are terrific.', '2009-09-05 22:18:15.000000', NULL, 1),
(5637453, 817909, 76335, '<td valign="top">A nice scene but way overprocessed for my tastes.</td>', 'A nice scene but way overprocessed for my tastes.', '2009-09-05 22:18:48.000000', NULL, 1),
(5637454, 818263, 76335, '<td valign="top">Abstract but still very accessible. Nice in black and white.</td>', 'Abstract but still very accessible. Nice in black and white.', '2009-09-05 22:19:22.000000', NULL, 1),
(5637456, 818355, 76335, '<td valign="top">Well executed, but I actually think a little <i>less</i> DOF would have been nice. It needs some context.</td>', 'Well executed, but I actually think a little less DOF would have been nice. It needs some context.', '2009-09-05 22:20:53.000000', NULL, 1),
(5637457, 817545, 76335, '<td valign="top">Wonderful contrast here.</td>', 'Wonderful contrast here.', '2009-09-05 22:22:00.000000', NULL, 1),
(5637458, 816739, 76335, '<td valign="top">Not sure I like the Topaz-like effect, but the colors are most appealing.</td>', 'Not sure I like the Topaz-like effect, but the colors are most appealing.', '2009-09-05 22:22:59.000000', NULL, 1),
(5637459, 817362, 76335, '<td valign="top">Great detail. Has a very classic feel to it -- like something out of an old book.</td>', 'Great detail. Has a very classic feel to it -- like something out of an old book.', '2009-09-05 22:23:49.000000', NULL, 1),
(5637460, 817235, 76335, '<td valign="top">Most excellent. Not much more to say. Wow!</td>', 'Most excellent. Not much more to say. Wow!', '2009-09-05 22:25:28.000000', NULL, 1),
(5637461, 818496, 76335, '<td valign="top">Those are some loooooong legs! Nice wide angle effect.</td>', 'Those are some loooooong legs! Nice wide angle effect.', '2009-09-05 22:26:24.000000', NULL, 1),
(5637463, 814798, 76335, '<td valign="top">I like the concept you were after, but this is way overprocessed.</td>', 'I like the concept you were after, but this is way overprocessed.', '2009-09-05 22:27:43.000000', NULL, 1),
(5637478, 817416, 76335, '<td valign="top">Nice moment. The blurry area in the foreground is a bit destracting...</td>', 'Nice moment. The blurry area in the foreground is a bit destracting...', '2009-09-05 22:30:38.000000', NULL, 1),
(5637481, 818475, 76335, '<td valign="top">Neat-O! That mic rally feels live.</td>', 'Neat-O! That mic rally feels live.', '2009-09-05 22:31:40.000000', NULL, 1),
(5637483, 817766, 76335, '<td valign="top">Nicely captured. Good photojournalism.</td>', 'Nicely captured. Good photojournalism.', '2009-09-05 22:32:32.000000', NULL, 1),
(5637484, 817174, 76335, '<td valign="top">Nice framing and I even like the mid-key sort of processing. I wonder if her right eye couldn''t have been in slightly sharper focus.</td>', 'Nice framing and I even like the mid-key sort of processing. I wonder if her right eye couldn''t have been in slightly sharper focus.', '2009-09-05 22:34:21.000000', NULL, 1),
(5637485, 817756, 76335, '<td valign="top">Great subject and the contrast is good. I wish it were just a little bit softer.</td>', 'Great subject and the contrast is good. I wish it were just a little bit softer.', '2009-09-05 22:36:16.000000', NULL, 1),
(5637486, 818504, 76335, '<td valign="top">Great! I have to wonder, though, what that little strip of sky is buying you here. Without it, it would be almost completely abstract, and to good effect, I think, but maybe that''s what you were trying to avoid. Anyway...</td>', 'Great! I have to wonder, though, what that little strip of sky is buying you here. Without it, it would be almost completely abstract, and to good effect, I think, but maybe that''s what you were trying to avoid. Anyway...', '2009-09-05 22:38:40.000000', NULL, 1),
(5637487, 814775, 76335, '<td valign="top">It''s a tired subject, but, well... this is really good.</td>', 'It''s a tired subject, but, well... this is really good.', '2009-09-05 22:39:30.000000', NULL, 1),
(5637490, 818231, 76335, '<td valign="top">An honest, if somewhat unflattering, portrait. I have to wonder about her nose -- is it the lighting that makes it look darker or a real feature? Minor quibbles/questions; it''s really very good.</td>', 'An honest, if somewhat unflattering, portrait. I have to wonder about her nose -- is it the lighting that makes it look darker or a real feature? Minor quibbles/questions; it''s really very good.', '2009-09-05 22:41:28.000000', NULL, 1),
(5637492, 818390, 76335, '<td valign="top">Nice, but I think it would have been more effective in black and white. The patterns, to me, are far more interesting than the colors.</td>', 'Nice, but I think it would have been more effective in black and white. The patterns, to me, are far more interesting than the colors.', '2009-09-05 22:42:37.000000', NULL, 1),
(5637494, 817450, 76335, '<td valign="top">Kind of unsettling. The bright light and orientation are both a bit of a surprise here. To good effect, though, I think. Great textures all around.</td>', 'Kind of unsettling. The bright light and orientation are both a bit of a surprise here. To good effect, though, I think. Great textures all around.', '2009-09-05 22:44:09.000000', NULL, 1),
(5637495, 817236, 76335, '<td valign="top">Excellent!</td>', 'Excellent!', '2009-09-05 22:44:21.000000', NULL, 1),
(5637500, 818407, 76335, '<td valign="top">Beautifully executed, though my overly analytic brain thinks it might have been more effective with the comp/framing more aligned to thirds.</td>', 'Beautifully executed, though my overly analytic brain thinks it might have been more effective with the comp/framing more aligned to thirds.', '2009-09-05 22:46:50.000000', NULL, 1),
(5637502, 818379, 76335, '<td valign="top">A fun (if somewhat disturbing) composition. The blown highlights take something away...</td>', 'A fun (if somewhat disturbing) composition. The blown highlights take something away...', '2009-09-05 22:47:52.000000', NULL, 1),
(5637503, 816597, 76335, '<td valign="top">Beautiful high key work.</td>', 'Beautiful high key work.', '2009-09-05 22:48:05.000000', NULL, 1),
(5637507, 818246, 76335, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2009-09-05 22:50:35.000000', NULL, 1),
(5637508, 817129, 76335, '<td valign="top">Very honest and endearing kid shot. Nice.</td>', 'Very honest and endearing kid shot. Nice.', '2009-09-05 22:52:04.000000', NULL, 1),
(5637510, 818264, 76335, '<td valign="top">Looks otherworldly. Nice executed.</td>', 'Looks otherworldly. Nice executed.', '2009-09-05 22:52:35.000000', NULL, 1),
(5637511, 818491, 76335, '<td valign="top">Great character study. Nice work all around.</td>', 'Great character study. Nice work all around.', '2009-09-05 22:53:40.000000', NULL, 1),
(5637512, 815477, 76335, '<td valign="top">Don''t shots like this always ribbon? Nice job!</td>', 'Don''t shots like this always ribbon? Nice job!', '2009-09-05 22:54:34.000000', NULL, 1),
(5637513, 818306, 76335, '<td valign="top">Just excellent. Wow. I''ll be curious to read about your set up.</td>', 'Just excellent. Wow. I''ll be curious to read about your set up.', '2009-09-05 22:55:14.000000', NULL, 1),
(5637548, 818497, 79357, '<td valign="top">Technically nothing spectacular, but her facial expresion is beautiful. An 8</td>', 'Technically nothing spectacular, but her facial expresion is beautiful. An 8', '2009-09-05 23:26:44.000000', NULL, 1),
(5637653, 818178, 80728, '<td valign="top">Love the sepia in this shot.</td>', 'Love the sepia in this shot.', '2009-09-06 02:28:53.000000', NULL, 1),
(5637701, 814840, 30982, '<td valign="top">Perhaps the strongest emotionally in the challenge - definitely one of my favorites.</td>', 'Perhaps the strongest emotionally in the challenge - definitely one of my favorites.', '2009-09-06 04:30:24.000000', NULL, 1),
(5637703, 817129, 30982, '<td valign="top">Very sweet, very honest portrait.  Nicely done!</td>', 'Very sweet, very honest portrait.  Nicely done!', '2009-09-06 04:31:24.000000', NULL, 1),
(5637704, 818268, 30982, '<td valign="top">Awesome light in those curls, amazing eyes, and what a pose!</td>', 'Awesome light in those curls, amazing eyes, and what a pose!', '2009-09-06 04:32:04.000000', NULL, 1),
(5637706, 818477, 30982, '<td valign="top">I think I''m developing a thing for goats.  This one is quite touching and sweet.</td>', 'I think I''m developing a thing for goats.  This one is quite touching and sweet.', '2009-09-06 04:32:51.000000', NULL, 1),
(5637707, 811835, 30982, '<td valign="top">Very touching.  Love the shallow DOF.</td>', 'Very touching.  Love the shallow DOF.', '2009-09-06 04:33:37.000000', NULL, 1),
(5637708, 818369, 30982, '<td valign="top">Wonderful sense of the day and place, if that makes sense - you definitely put me there to share it.</td>', 'Wonderful sense of the day and place, if that makes sense - you definitely put me there to share it.', '2009-09-06 04:34:23.000000', NULL, 1),
(5637709, 818363, 30982, '<td valign="top">Quite intriguing!!</td>', 'Quite intriguing!!', '2009-09-06 04:34:32.000000', NULL, 1),
(5637710, 817836, 30982, '<td valign="top">Yes!!!  How very delightful!</td>', 'Yes!!!  How very delightful!', '2009-09-06 04:35:21.000000', NULL, 1),
(5637711, 815638, 30982, '<td valign="top">Excellent capture.  Was it ill or dying?  I can''t see them sitting still otherwise.  :-(</td>', 'Excellent capture.  Was it ill or dying?  I can''t see them sitting still otherwise.  :-(', '2009-09-06 04:36:03.000000', NULL, 1),
(5637712, 818362, 30982, '<td valign="top">Fun!!  Love this mini-but-wide encapsulation of summer.</td>', 'Fun!!  Love this mini-but-wide encapsulation of summer.', '2009-09-06 04:36:41.000000', NULL, 1),
(5637713, 816016, 30982, '<td valign="top">An excellent portrait and very much a boy next door kinda thing, though he could easily be the model next door as well.</td>', 'An excellent portrait and very much a boy next door kinda thing, though he could easily be the model next door as well.', '2009-09-06 04:37:42.000000', NULL, 1),
(5637714, 818321, 30982, '<td valign="top">What an elegant creature, shaggy fur and all.</td>', 'What an elegant creature, shaggy fur and all.', '2009-09-06 04:39:36.000000', NULL, 1),
(5637715, 816176, 30982, '<td valign="top">Quite adorable, really.</td>', 'Quite adorable, really.', '2009-09-06 04:39:46.000000', NULL, 1),
(5637716, 817891, 30982, '<td valign="top">He looks kinda bedraggled.  But still cute.</td>', 'He looks kinda bedraggled.  But still cute.', '2009-09-06 04:40:24.000000', NULL, 1),
(5637717, 811325, 30982, '<td valign="top">Lovely use of what I''m guessing is foreground bokeh to frame this.  Soft and gentle.</td>', 'Lovely use of what I''m guessing is foreground bokeh to frame this.  Soft and gentle.', '2009-09-06 04:40:50.000000', NULL, 1),
(5637718, 817523, 30982, '<td valign="top">Evil Coke goats.... love the processing!</td>', 'Evil Coke goats.... love the processing!', '2009-09-06 04:41:10.000000', NULL, 1),
(5637719, 818511, 30982, '<td valign="top">Pretty good composition with good use of the diagonals and that lovely gold in the distance.  A touch "dull" in that it seems to need a bit of sharpening and perhaps a bit more brightness/contrast.  Looks like it was a gorgeous calm day and a beautiful place to spend that day!</td>', 'Pretty good composition with good use of the diagonals and that lovely gold in the distance.  A touch "dull" in that it seems to need a bit of sharpening and perhaps a bit more brightness/contrast.  Looks like it was a gorgeous calm day and a beautiful place to spend that day!', '2009-09-06 04:44:25.000000', NULL, 1),
(5637789, 818379, 83313, '<td valign="top">Is that a trash can she''s in?! Looking forward to reading the story behind this entry.</td>', 'Is that a trash can she''s in?! Looking forward to reading the story behind this entry.', '2009-09-06 09:57:07.000000', NULL, 1),
(5637790, 816784, 83313, '<td valign="top">Love the dimension and tones in this one. I think you caught the light at just the perfect moment.</td>', 'Love the dimension and tones in this one. I think you caught the light at just the perfect moment.', '2009-09-06 09:58:13.000000', NULL, 1),
(5637792, 817629, 83313, '<td valign="top">My first thought was "too busy", but then I kept looking and realized that''s the point of this scene and it''s appeal. A thick, man made forest of masts.</td>', 'My first thought was "too busy", but then I kept looking and realized that''s the point of this scene and it''s appeal. A thick, man made forest of masts.', '2009-09-06 10:02:00.000000', NULL, 1),
(5637800, 818324, 76335, '<td valign="top">There''s nothing about them that really says that they''re tourists. No gawking at buildings, clashing attire, cameras, etc. -- at least, not that I can see. In fact, they''re not doing anything interesting at all, really. The really interesting stuff (like that grand castle) is secondary to the shot.</td>', 'There''s nothing about them that really says that they''re tourists. No gawking at buildings, clashing attire, cameras, etc. -- at least, not that I can see. In fact, they''re not doing anything interesting at all, really. The really interesting stuff (like that grand castle) is secondary to the shot.', '2009-09-06 10:09:03.000000', NULL, 1),
(5637803, 818503, 76335, '<td valign="top">The tilt and slight blur is very effective.</td>', 'The tilt and slight blur is very effective.', '2009-09-06 10:10:09.000000', NULL, 1),
(5637804, 818480, 76335, '<td valign="top">I''m not sure you had to resort to Photoshop trickery to show off those beautiful eyes. I think leaving this in color would have been just fine.</td>', 'I''m not sure you had to resort to Photoshop trickery to show off those beautiful eyes. I think leaving this in color would have been just fine.', '2009-09-06 10:12:36.000000', NULL, 1),
(5637805, 814840, 76335, '<td valign="top">I had to come back for a second look just now. Really good!</td>', 'I had to come back for a second look just now. Really good!', '2009-09-06 10:13:34.000000', NULL, 1),
(5637806, 817254, 76335, '<td valign="top">Got milk? The lighting on her lip is a bit distracting.</td>', 'Got milk? The lighting on her lip is a bit distracting.', '2009-09-06 10:15:03.000000', NULL, 1),
