(5639218, 817520, 88247, '<td valign="top">So cute and I love the expression on the face:-)<br/>Great shot.</td>', 'So cute and I love the expression on the face:-)Great shot.', '2009-09-07 16:50:02.000000', NULL, 1),
(5639220, 817056, 88247, '<td valign="top">This shot takes me back to my happy childhood days:-)<br/>Paddling in the freezing cold waters up the "Duddon Valley"<br/>I have promised myself that i will return there one day,it was such a beautiful spot.<br/>Thanks for the memories with this beautiful masterpiece.</td>', 'This shot takes me back to my happy childhood days:-)Paddling in the freezing cold waters up the "Duddon Valley"I have promised myself that i will return there one day,it was such a beautiful spot.Thanks for the memories with this beautiful masterpiece.', '2009-09-07 16:50:52.000000', NULL, 1),
(5639222, 817974, 88247, '<td valign="top">The lighting,the colour, the frame, and the black background,I just love everything about this shot.<br/>Beautiful:-)</td>', 'The lighting,the colour, the frame, and the black background,I just love everything about this shot.Beautiful:-)', '2009-09-07 16:53:49.000000', NULL, 1),
